import docx, re
d = docx.Document("inputs/offer_letter_template.docx")
found=set()
def scan(p):
    t="".join(r.text for r in p.runs)
    for m in re.finditer(r"\{\{[^}]*\}\}", t):
        found.add(m.group(0))
for p in d.paragraphs: scan(p)
def walk(tbl):
    for row in tbl.rows:
        for cell in row.cells:
            for p in cell.paragraphs: scan(p)
            for n in cell.tables: walk(n)
for t in d.tables: walk(t)
for s in d.sections:
    for part in (s.header,s.first_page_header,s.even_page_header,s.footer,s.first_page_footer,s.even_page_footer):
        if part:
            for p in part.paragraphs: scan(p)
            for t in part.tables: walk(t)
print(sorted(found))
EOF

